messages.content:
Berikut manifest game edukasi Endless Runner bertema tokoh Proklamasi dan Sumpah Pemuda dengan tema Clean Modern dan tingkat Santai. Asumsi penting: item jebakan miskonsepsi diwakili oleh tokoh Perumus Naskah (Hatta, Soebardjo, Sayuti Melik) yang menegaskan naskah tidak ditulis Soekarno seorang diri.

```js
AISYS.defineGame({
  schema: 1, kit: "endless-runner",
  id: "proklamasi-pemuda-run", title: "Proklamasi & Pemuda Run", seed: "proklamasi-01",
  theme: { preset: "clean-modern" },

  learning: {
    subject: "Sejarah Indonesia",
    concept: "Peran tokoh Proklamasi Kemerdekaan dan Sumpah Pemuda",
    objectives: [
      "Mengelompokkan tokoh berdasarkan perannya dalam Proklamasi dan Sumpah Pemuda",
      "Mengenali perumus naskah Proklamasi selain Soekarno"
    ],
    misconceptions: ["Teks Proklamasi ditulis Soekarno seorang diri"],
    mode: "category",
    categories: [
      { id: "proklamator", label: "Proklamator", color: "#3FA34D" },
      { id: "perumus",     label: "Perumus Naskah", color: "#2F80ED" },
      { id: "sumpah",      label: "Tokoh Sumpah Pemuda", color: "#E5484D" }
    ],
    items: [
      { id: "soekarno",   label: "Soekarno",   category: "proklamator", explain: "Membacakan teks Proklamasi pada 17 Agustus 1945." },
      { id: "hatta",      label: "Mohammad Hatta", category: "proklamator", explain: "Mendampingi Soekarno menandatangani teks Proklamasi." },
      { id: "fatmawati",  label: "Fatmawati",  category: "proklamator", explain: "Menjahit bendera pusaka yang dikibarkan saat Proklamasi." },
      { id: "soebardjo",  label: "Achmad Soebardjo", category: "perumus", explain: "Ikut merumuskan naskah Proklamasi bersama Soekarno dan Hatta." },
      { id: "sayuti",     label: "Sayuti Melik", category: "perumus", explain: "Mengetik naskah Proklamasi hasil rumusan para tokoh." },
      { id: "bm-diah",    label: "BM Diah",    category: "perumus", explain: "Menyimpan naskah asli Proklamasi yang sempat dibuang." },
      { id: "wr-supratman", label: "WR Supratman", category: "sumpah", explain: "Pencipta lagu Indonesia Raya yang dikumandangkan di Kongres Pemuda II." },
      { id: "yamin",      label: "Mohammad Yamin", category: "sumpah", explain: "Ikut merumuskan isi Sumpah Pemuda dalam Kongres Pemuda II." },
      { id: "soegondo",   label: "Soegondo Djojopoespito", category: "sumpah", explain: "Ketua Kongres Pemuda II yang melahirkan Sumpah Pemuda." }
    ],
    target: { rotateAfterCorrect: 5, bias: 0.5 }
  },

  player: { x: 220, w: 44, h: 56, gravity: 2400, jumpVelocity: 900, lives: 5, invulnerableSec: 1.2 },
  world:  { groundY: 600, speed: 300, maxSpeed: 600, accel: 4 },

  spawner: {
    interval: [0.9, 1.5],
    table: [
      { type: "hazard", id: "batu",     w: 44, h: 48, weight: 3 },
      { type: "hazard", id: "tiang",    w: 30, h: 70, weight: 2 },
      { type: "hazard", id: "genangan", w: 90, h: 24, weight: 2 },
      { type: "item", weight: 5, heights: ["ground", "mid", "high"] }
    ]
  },

  rules: {
    perSecond: 5,
    correct: { score: 50, sfx: "coin" },
    wrong:   { score: -20, sfx: "hit", showExplain: true },
    hazard:  { lives: -1, sfx: "hit", shake: 8 },
    combo:   { step: 5, max: 4 },
    difficulty: { everySec: 20, speed: 20 }
  }
});
// END_OF_MANIFEST
```
